create table if not exists public.student_bulk_operation_jobs(
  id bigint generated by default as identity primary key,
  tenant_id bigint not null references public.tenants(id) on delete restrict,
  branch_id bigint not null,
  operation_type text not null check(operation_type in('import','promotion','renewal')),
  idempotency_key text not null check(length(idempotency_key) between 16 and 128),
  state text not null default 'processing' check(state in('processing','completed','partial','needs_review','failed')),
  total_items integer not null default 0 check(total_items>=0),
  succeeded_items integer not null default 0 check(succeeded_items>=0),
  blocked_items integer not null default 0 check(blocked_items>=0),
  failed_items integer not null default 0 check(failed_items>=0),
  summary jsonb not null default '{}'::jsonb,
  actor_membership_id bigint,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  unique(tenant_id,id),
  unique(tenant_id,idempotency_key),
  foreign key(tenant_id,branch_id) references public.branches(tenant_id,id) on delete restrict,
  foreign key(tenant_id,actor_membership_id) references public.memberships(tenant_id,id) on delete restrict
);

create table if not exists public.student_bulk_operation_items(
  id bigint generated by default as identity primary key,
  tenant_id bigint not null references public.tenants(id) on delete restrict,
  job_id bigint not null,
  item_number integer not null check(item_number>0),
  student_person_id bigint,
  input_label text,
  state text not null check(state in('created','planned','blocked','failed')),
  result jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  unique(tenant_id,id),
  unique(tenant_id,job_id,item_number),
  foreign key(tenant_id,job_id) references public.student_bulk_operation_jobs(tenant_id,id) on delete cascade,
  foreign key(tenant_id,student_person_id) references public.student_profiles(tenant_id,person_id) on delete restrict
);

create index if not exists student_bulk_operation_jobs_branch_recent_idx on public.student_bulk_operation_jobs(tenant_id,branch_id,created_at desc);
create index if not exists student_bulk_operation_items_job_idx on public.student_bulk_operation_items(tenant_id,job_id,item_number);

alter table public.student_bulk_operation_jobs enable row level security;
alter table public.student_bulk_operation_items enable row level security;
revoke all on public.student_bulk_operation_jobs,public.student_bulk_operation_items from public,anon,authenticated;
grant all on public.student_bulk_operation_jobs,public.student_bulk_operation_items to service_role;

create or replace function public.get_student_lifecycle_center_v1(p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint)
returns jsonb language plpgsql stable set search_path to pg_catalog, extensions
as $fn$
declare v_membership bigint;v_sessions jsonb;v_groups jsonb;v_students jsonb;v_jobs jsonb;begin
  select m.id into v_membership from public.memberships m
  where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active'
    and (m.starts_at is null or m.starts_at<=now()) and (m.ends_at is null or m.ends_at>now())
    and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id))
    and exists(
      select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id
      where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code in('students.profile.read','academics.enrollment.manage','academics.structure.read')
      group by mr.membership_id having count(distinct rp.permission_code)=3
    ) order by m.created_at limit 1;
  if v_membership is null then raise exception 'student lifecycle workspace permission denied';end if;
  if not exists(select 1 from public.branches b where b.tenant_id=p_tenant_id and b.id=p_branch_id and b.status='active') then raise exception 'active branch required';end if;

  select coalesce(jsonb_agg(row_to_json(x) order by x.starts_on,x.id),'[]'::jsonb) into v_sessions from(
    select s.id,s.key,s.labels,s.starts_on,s.ends_on,s.status,s.is_default from public.academic_sessions s where s.tenant_id=p_tenant_id and s.status<>'archived'
  )x;
  select coalesce(jsonb_agg(row_to_json(x) order by x.session_id,x.id),'[]'::jsonb) into v_groups from(
    select g.id,g.session_id,g.program_id,g.level_id,g.key,g.labels,g.capacity,g.status,p.labels program_labels
    from public.academic_groups g join public.programs p on p.tenant_id=g.tenant_id and p.id=g.program_id
    where g.tenant_id=p_tenant_id and g.branch_id=p_branch_id and g.status='active'
  )x;
  select coalesce(jsonb_agg(row_to_json(x) order by x.display_name),'[]'::jsonb) into v_students from(
    select distinct on(e.student_person_id) e.student_person_id,sp.student_number,p.display_name,e.id enrollment_id,e.session_id,e.program_id,e.group_id,e.starts_on,e.status
    from public.enrollments e join public.student_profiles sp on sp.tenant_id=e.tenant_id and sp.person_id=e.student_person_id
    join public.persons p on p.tenant_id=e.tenant_id and p.id=e.student_person_id
    where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.status in('active','paused') and sp.status in('active','admitted')
    order by e.student_person_id,e.starts_on desc,e.id desc
  )x;
  select coalesce(jsonb_agg(row_to_json(x) order by x.created_at desc,x.id desc),'[]'::jsonb) into v_jobs from(
    select j.id,j.operation_type,j.state,j.total_items,j.succeeded_items,j.blocked_items,j.failed_items,j.summary,j.created_at,j.completed_at
    from public.student_bulk_operation_jobs j where j.tenant_id=p_tenant_id and j.branch_id=p_branch_id order by j.created_at desc,j.id desc limit 30
  )x;
  return jsonb_build_object('sessions',v_sessions,'groups',v_groups,'students',v_students,'jobs',v_jobs);
end;$fn$;

create or replace function public.prepare_next_academic_session_v1(
  p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_source_session_id bigint,p_key text,p_labels jsonb,p_starts_on date,p_ends_on date
) returns jsonb language plpgsql set search_path to pg_catalog, extensions
as $fn$
declare v_membership bigint;v_key text:=lower(btrim(coalesce(p_key,'')));v_source_end date;v_session_id bigint;v_group_count integer;v_existing boolean:=false;begin
  select m.id into v_membership from public.memberships m
  where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active'
    and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id))
    and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code='academics.structure.manage')
  order by m.created_at limit 1;
  if v_membership is null then raise exception 'academic structure permission denied';end if;
  if v_key !~ '^[a-z0-9][a-z0-9_-]{1,63}$' then raise exception 'valid academic session key required';end if;
  if p_labels is null or jsonb_typeof(p_labels)<>'object' or nullif(btrim(coalesce(p_labels->>'en','')),'') is null then raise exception 'English academic session label required';end if;
  if p_starts_on is null or p_ends_on is null or p_ends_on<=p_starts_on then raise exception 'valid academic session dates required';end if;
  select s.ends_on into v_source_end from public.academic_sessions s where s.tenant_id=p_tenant_id and s.id=p_source_session_id and s.status in('active','closing','closed');
  if v_source_end is null then raise exception 'source academic session is unavailable';end if;
  if p_starts_on<=v_source_end then raise exception 'next academic session must start after the source session ends';end if;
  perform pg_advisory_xact_lock(hashtextextended('academic-session:'||p_tenant_id::text||':'||v_key,0));
  select s.id into v_session_id from public.academic_sessions s where s.tenant_id=p_tenant_id and s.key=v_key;
  if v_session_id is null then
    insert into public.academic_sessions(tenant_id,key,labels,starts_on,ends_on,status,is_default)
    values(p_tenant_id,v_key,p_labels,p_starts_on,p_ends_on,'draft',false) returning id into v_session_id;
  else
    v_existing:=true;
    if not exists(select 1 from public.academic_sessions s where s.tenant_id=p_tenant_id and s.id=v_session_id and s.starts_on=p_starts_on and s.ends_on=p_ends_on) then raise exception 'academic session key already exists with different dates';end if;
  end if;
  insert into public.academic_groups(tenant_id,branch_id,session_id,program_id,level_id,key,labels,capacity,primary_teacher_person_id,cohort_metadata,status)
  select g.tenant_id,g.branch_id,v_session_id,g.program_id,g.level_id,g.key,g.labels,g.capacity,null,g.cohort_metadata,'active'
  from public.academic_groups g
  where g.tenant_id=p_tenant_id and g.branch_id=p_branch_id and g.session_id=p_source_session_id and g.status='active'
  on conflict(tenant_id,branch_id,session_id,key) do nothing;
  select count(*)::integer into v_group_count from public.academic_groups g where g.tenant_id=p_tenant_id and g.branch_id=p_branch_id and g.session_id=v_session_id and g.status='active';
  insert into public.audit_events(tenant_id,branch_id,actor_identity_id,actor_membership_id,action,outcome,entity_type,entity_id,correlation_id,after_state)
  values(p_tenant_id,p_branch_id,p_identity_id,v_membership,'academics.session.prepare_next','succeeded','academic_session',v_session_id::text,gen_random_uuid(),jsonb_build_object('source_session_id',p_source_session_id,'starts_on',p_starts_on,'ends_on',p_ends_on,'groups_cloned',v_group_count,'existing',v_existing));
  return jsonb_build_object('session_id',v_session_id,'state','draft','groups_cloned',v_group_count,'unchanged',v_existing);
end;$fn$;

create or replace function public.import_students_batch_v1(
  p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_session_id bigint,p_program_id bigint,p_group_id bigint,p_joined_on date,p_rows jsonb,p_request_key text
) returns jsonb language plpgsql set search_path to pg_catalog, extensions
as $fn$
declare
  v_membership bigint;v_job bigint;v_existing public.student_bulk_operation_jobs%rowtype;v_entry record;v_row jsonb;v_result jsonb;v_name text;v_person bigint;v_success integer:=0;v_blocked integer:=0;v_failed integer:=0;v_total integer;v_state text;v_item_state text;v_item_result jsonb;v_guardian jsonb;
begin
  if p_request_key is null or length(p_request_key) not between 16 and 128 then raise exception 'valid import request key required';end if;
  if p_rows is null or jsonb_typeof(p_rows)<>'array' then raise exception 'student import rows must be an array';end if;
  v_total:=jsonb_array_length(p_rows);if v_total<1 or v_total>100 then raise exception 'student import supports 1 to 100 rows per batch';end if;
  select m.id into v_membership from public.memberships m
  where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active'
    and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id))
    and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code in('people.person.manage','students.profile.update','academics.enrollment.manage') group by mr.membership_id having count(distinct rp.permission_code)=3)
  order by m.created_at limit 1;
  if v_membership is null then raise exception 'student import permission denied';end if;
  select * into v_existing from public.student_bulk_operation_jobs j where j.tenant_id=p_tenant_id and j.idempotency_key=p_request_key;
  if v_existing.id is not null then return jsonb_build_object('job_id',v_existing.id,'state',v_existing.state,'total_items',v_existing.total_items,'succeeded_items',v_existing.succeeded_items,'blocked_items',v_existing.blocked_items,'failed_items',v_existing.failed_items,'unchanged',true);end if;
  insert into public.student_bulk_operation_jobs(tenant_id,branch_id,operation_type,idempotency_key,state,total_items,actor_membership_id,summary)
  values(p_tenant_id,p_branch_id,'import',p_request_key,'processing',v_total,v_membership,jsonb_build_object('session_id',p_session_id,'program_id',p_program_id,'group_id',p_group_id,'joined_on',p_joined_on)) returning id into v_job;
  for v_entry in select value,ordinality from jsonb_array_elements(p_rows) with ordinality loop
    v_row:=v_entry.value;v_name:=btrim(coalesce(v_row->>'display_name',''));v_person:=null;v_item_result:='{}'::jsonb;
    begin
      if jsonb_typeof(v_row)<>'object' then raise exception 'row must be an object';end if;
      v_guardian:=case when v_row ? 'guardian' and jsonb_typeof(v_row->'guardian')='object' then v_row->'guardian' else null end;
      select public.create_student_direct(
        p_identity_id,p_tenant_id,p_branch_id,v_name,nullif(btrim(coalesce(v_row->>'name_native','')),''),
        nullif(v_row->>'date_of_birth','')::date,nullif(v_row->>'gender',''),coalesce(nullif(v_row->>'preferred_locale',''),'en'),
        p_session_id,p_program_id,p_group_id,p_joined_on,null,null,null,v_guardian,false
      ) into v_result;
      if coalesce((v_result->>'duplicate_review_required')::boolean,false) then
        v_item_state:='blocked';v_blocked:=v_blocked+1;v_item_result:=jsonb_build_object('reason','duplicate_review_required','candidate_count',coalesce((v_result->>'candidate_count')::integer,0));
      elsif coalesce((v_result->>'created')::boolean,false) then
        v_item_state:='created';v_success:=v_success+1;v_person:=(v_result->>'person_id')::bigint;v_item_result:=v_result;
      else
        v_item_state:='failed';v_failed:=v_failed+1;v_item_result:=jsonb_build_object('reason','student runtime did not create a record');
      end if;
    exception when others then
      v_item_state:='failed';v_failed:=v_failed+1;v_item_result:=jsonb_build_object('reason',sqlerrm);
    end;
    insert into public.student_bulk_operation_items(tenant_id,job_id,item_number,student_person_id,input_label,state,result)
    values(p_tenant_id,v_job,v_entry.ordinality::integer,v_person,left(nullif(v_name,''),160),v_item_state,v_item_result);
  end loop;
  v_state:=case when v_success=v_total then 'completed' when v_success=0 and v_failed>0 then 'failed' when v_success=0 and v_blocked>0 and v_failed=0 then 'needs_review' else 'partial' end;
  update public.student_bulk_operation_jobs set state=v_state,succeeded_items=v_success,blocked_items=v_blocked,failed_items=v_failed,completed_at=now(),summary=summary||jsonb_build_object('created',v_success,'needs_review',v_blocked,'failed',v_failed) where tenant_id=p_tenant_id and id=v_job;
  insert into public.audit_events(tenant_id,branch_id,actor_identity_id,actor_membership_id,action,outcome,entity_type,entity_id,correlation_id,after_state)
  values(p_tenant_id,p_branch_id,p_identity_id,v_membership,'students.bulk.import','succeeded','student_bulk_operation_job',v_job::text,gen_random_uuid(),jsonb_build_object('state',v_state,'total',v_total,'created',v_success,'blocked',v_blocked,'failed',v_failed));
  return jsonb_build_object('job_id',v_job,'state',v_state,'total_items',v_total,'succeeded_items',v_success,'blocked_items',v_blocked,'failed_items',v_failed,'unchanged',false);
end;$fn$;

create or replace function public.plan_student_rollover_batch_v1(
  p_identity_id uuid,p_tenant_id bigint,p_branch_id bigint,p_student_person_ids bigint[],p_target_session_id bigint,p_target_group_id bigint,p_mode text,p_request_key text
) returns jsonb language plpgsql set search_path to pg_catalog, extensions
as $fn$
declare
  v_membership bigint;v_mode text:=lower(btrim(coalesce(p_mode,'')));v_job bigint;v_existing public.student_bulk_operation_jobs%rowtype;v_target record;v_person bigint;v_current public.enrollments%rowtype;v_new_enrollment bigint;v_success integer:=0;v_blocked integer:=0;v_failed integer:=0;v_total integer;v_state text;v_reason text;v_number text;v_name text;v_capacity_used integer;
begin
  if p_request_key is null or length(p_request_key) not between 16 and 128 then raise exception 'valid rollover request key required';end if;
  if v_mode not in('promotion','renewal') then raise exception 'rollover mode must be promotion or renewal';end if;
  if p_student_person_ids is null then raise exception 'students are required';end if;
  select count(distinct x)::integer into v_total from unnest(p_student_person_ids)x where x is not null;
  if v_total<1 or v_total>250 then raise exception 'rollover supports 1 to 250 students per batch';end if;
  select m.id into v_membership from public.memberships m
  where m.tenant_id=p_tenant_id and m.identity_id=p_identity_id and m.status='active'
    and (m.all_branches or exists(select 1 from public.membership_branch_scopes s where s.tenant_id=m.tenant_id and s.membership_id=m.id and s.branch_id=p_branch_id))
    and exists(select 1 from public.membership_roles mr join public.role_permissions rp on rp.tenant_id=mr.tenant_id and rp.role_id=mr.role_id where mr.tenant_id=m.tenant_id and mr.membership_id=m.id and rp.permission_code in('academics.enrollment.manage','students.profile.read') group by mr.membership_id having count(distinct rp.permission_code)=2)
  order by m.created_at limit 1;
  if v_membership is null then raise exception 'student rollover permission denied';end if;
  select s.id session_id,s.starts_on,s.status session_status,g.id group_id,g.program_id,g.level_id,g.capacity into v_target
  from public.academic_sessions s join public.academic_groups g on g.tenant_id=s.tenant_id and g.session_id=s.id
  where s.tenant_id=p_tenant_id and s.id=p_target_session_id and s.status in('draft','active') and g.id=p_target_group_id and g.branch_id=p_branch_id and g.status='active';
  if v_target.session_id is null then raise exception 'target session and group are invalid';end if;
  select * into v_existing from public.student_bulk_operation_jobs j where j.tenant_id=p_tenant_id and j.idempotency_key=p_request_key;
  if v_existing.id is not null then return jsonb_build_object('job_id',v_existing.id,'state',v_existing.state,'total_items',v_existing.total_items,'succeeded_items',v_existing.succeeded_items,'blocked_items',v_existing.blocked_items,'failed_items',v_existing.failed_items,'unchanged',true);end if;
  insert into public.student_bulk_operation_jobs(tenant_id,branch_id,operation_type,idempotency_key,state,total_items,actor_membership_id,summary)
  values(p_tenant_id,p_branch_id,v_mode,p_request_key,'processing',v_total,v_membership,jsonb_build_object('target_session_id',p_target_session_id,'target_group_id',p_target_group_id)) returning id into v_job;
  select count(*)::integer into v_capacity_used from public.enrollments e where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.session_id=p_target_session_id and e.group_id=p_target_group_id and e.status in('planned','active','paused');
  for v_person in select distinct x from unnest(p_student_person_ids)x where x is not null order by x loop
    v_reason:=null;v_new_enrollment:=null;
    select e.* into v_current from public.enrollments e where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.student_person_id=v_person and e.status in('active','paused') order by e.starts_on desc,e.id desc limit 1;
    select sp.student_number,p.display_name into v_number,v_name from public.student_profiles sp join public.persons p on p.tenant_id=sp.tenant_id and p.id=sp.person_id where sp.tenant_id=p_tenant_id and sp.person_id=v_person;
    if v_current.id is null then v_reason:='active enrollment not found';
    elsif v_current.session_id=p_target_session_id then v_reason:='student is already in the target session';
    elsif exists(select 1 from public.enrollments e where e.tenant_id=p_tenant_id and e.branch_id=p_branch_id and e.student_person_id=v_person and e.session_id=p_target_session_id and e.status<>'cancelled') then v_reason:='target-session enrollment already exists';
    elsif v_mode='renewal' and v_current.program_id<>v_target.program_id then v_reason:='renewal must remain in the same program';
    elsif v_target.capacity is not null and v_capacity_used>=v_target.capacity then v_reason:='target group capacity reached';
    end if;
    if v_reason is not null then
      v_blocked:=v_blocked+1;
      insert into public.student_bulk_operation_items(tenant_id,job_id,item_number,student_person_id,input_label,state,result)
      values(p_tenant_id,v_job,v_success+v_blocked+v_failed,v_person,left(coalesce(v_number||' · ','')||coalesce(v_name,v_person::text),160),'blocked',jsonb_build_object('reason',v_reason));
      continue;
    end if;
    begin
      insert into public.enrollments(tenant_id,branch_id,student_person_id,session_id,program_id,level_id,group_id,starts_on,status)
      values(p_tenant_id,p_branch_id,v_person,p_target_session_id,v_target.program_id,v_target.level_id,p_target_group_id,v_target.starts_on,'planned') returning id into v_new_enrollment;
      insert into public.enrollment_events(tenant_id,enrollment_id,event_type,from_state,to_state,reason,actor_membership_id,correlation_id)
      values(p_tenant_id,v_new_enrollment,'created',jsonb_build_object('source_enrollment_id',v_current.id,'source_session_id',v_current.session_id),jsonb_build_object('status','planned','session_id',p_target_session_id,'group_id',p_target_group_id,'program_id',v_target.program_id),v_mode||' planned',v_membership,gen_random_uuid());
      v_success:=v_success+1;v_capacity_used:=v_capacity_used+1;
      insert into public.student_bulk_operation_items(tenant_id,job_id,item_number,student_person_id,input_label,state,result)
      values(p_tenant_id,v_job,v_success+v_blocked+v_failed,v_person,left(coalesce(v_number||' · ','')||coalesce(v_name,v_person::text),160),'planned',jsonb_build_object('enrollment_id',v_new_enrollment,'target_session_id',p_target_session_id,'target_group_id',p_target_group_id,'mode',v_mode));
    exception when others then
      v_failed:=v_failed+1;
      insert into public.student_bulk_operation_items(tenant_id,job_id,item_number,student_person_id,input_label,state,result)
      values(p_tenant_id,v_job,v_success+v_blocked+v_failed,v_person,left(coalesce(v_number||' · ','')||coalesce(v_name,v_person::text),160),'failed',jsonb_build_object('reason',sqlerrm));
    end;
  end loop;
  v_state:=case when v_success=v_total then 'completed' when v_success=0 and v_failed>0 then 'failed' when v_success=0 and v_blocked>0 and v_failed=0 then 'needs_review' else 'partial' end;
  update public.student_bulk_operation_jobs set state=v_state,succeeded_items=v_success,blocked_items=v_blocked,failed_items=v_failed,completed_at=now(),summary=summary||jsonb_build_object('planned',v_success,'blocked',v_blocked,'failed',v_failed) where tenant_id=p_tenant_id and id=v_job;
  insert into public.audit_events(tenant_id,branch_id,actor_identity_id,actor_membership_id,action,outcome,entity_type,entity_id,correlation_id,after_state)
  values(p_tenant_id,p_branch_id,p_identity_id,v_membership,'students.bulk.'||v_mode,'succeeded','student_bulk_operation_job',v_job::text,gen_random_uuid(),jsonb_build_object('state',v_state,'total',v_total,'planned',v_success,'blocked',v_blocked,'failed',v_failed,'target_session_id',p_target_session_id,'target_group_id',p_target_group_id));
  return jsonb_build_object('job_id',v_job,'state',v_state,'total_items',v_total,'succeeded_items',v_success,'blocked_items',v_blocked,'failed_items',v_failed,'unchanged',false);
end;$fn$;

